program = '''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    candidates = []
    for axis, n, m in ((0, h, w), (1, w, h)):
        lines = []
        for i in range(n):
            vals = [grid[i][j] for j in range(m)] if axis == 0 else [grid[j][i] for j in range(m)]
            if vals[0] != bg and all(v == vals[0] for v in vals):
                lines.append(i)
        if lines:
            bounds = [-1] + lines + [n]
            spans = [(bounds[k] + 1, bounds[k + 1]) for k in range(len(bounds) - 1)]
            lengths = [b - a for a, b in spans]
            if len(set(lengths)) == 1 and lengths[0] > 0:
                candidates.append((axis, lines, spans))
    if not candidates:
        return [row[:] for row in grid]
    axis, lines, spans = max(candidates, key=lambda x: len(x[1]))
    out = [row[:] for row in grid]
    size = spans[0][1] - spans[0][0]
    tile_count = len(spans)
    orth = w if axis == 0 else h
    for offset in range(size):
        for j in range(orth):
            found = None
            for a, _ in spans:
                pos = a + offset
                value = grid[pos][j] if axis == 0 else grid[j][pos]
                if value != bg:
                    found = value
                    break
            if found is not None:
                for a, _ in spans:
                    pos = a + offset
                    if axis == 0:
                        out[pos][j] = found
                    else:
                        out[j][pos] = found
    return out
'''
